(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[769],{1604:(e,t,r)=>{"use strict";r.d(t,{P:()=>l});var s=r(8017),i=r(4837),n=r(7487),a=r(2203);let l=e=>{let{content:t,children:r}=e;return(0,s.jsxs)(a.U,{title:t.heading,heading:t.heading,children:[t.sections.map((e,t)=>{var r;return(0,s.jsxs)(n.wn,{title:e.title,children:[null===(r=e.paragraphs)||void 0===r?void 0:r.map((e,t)=>(0,s.jsx)(n.fz,{children:(0,s.jsx)(i.s,{value:e})},t)),e.lines&&(0,s.jsx)(n.K,{lines:e.lines})]},t)}),r]})}},2667:(e,t,r)=>{"use strict";r.r(t),r.d(t,{default:()=>a});var s=r(8017),i=r(1604);let n={heading:"Общи условия",sections:[{paragraphs:["Този сайт е собственост на „ВИНЕРБЕРГЕР” ЕООД, с регистрация и адрес на управление в гр. София 1172, район Изгрев, ж.к. „Дианабад”, ул. „Пимен Зографски” № 4, бизнес сграда 2, ет. 2, ап. 1. Дружеството е регистрирано в Търговски регистър при агенция по вписванията с ЕИК 131343496","С отварянето на настоящия сайт Вие давате съгласието си за ползване на услугите и възможностите, които предлага той, вкл., но не само, с използването на Cookies (бисквитки) и други технологии, които са описани по-долу накратко. В случай, че описанието, съдържащо се по-долу, по Вашата преценка не е достатъчно, за да прецените степента на сигурност на Вашия компютър, препоръчваме да не използвате настоящия сайт, преди да сте получили квалифицирани разяснения по въпросите, по които се нуждаете от допълнителна информация.","Моля, прочетете тази страница внимателно, преди да ползвате сайта. Поместените тук информация и условия за ползване се отнасят за всички потребители, които посещават уебсайта на https://www.wienerberger.bg/ както и https://ceni.wienerberger.bg/"]},{title:"Цел на сайта",paragraphs:["Целта на сайта на https://ceni.wienerberger.bg/ е да предостави на потребителите безплатно и достъпно пълна информация за някои от продуктите, които „ВИНЕРБЕРГЕР” ЕООД предлага на българския пазар.","Сайтът е предназначен за използване на български език и съгласно законите на Република България."]},{title:"Използване на IP адреси, бисквитки (cookies) и други технически данни",paragraphs:["С цел подобряване качеството на уебсайта, ние наблюдаваме кои негови секции се посещават и колко време продължават тези посещения. Този мониторинг се осъществява чрез регистрация на IP адресите на компютрите на потребителите, а също и чрез използване на бисквитки. Регистрацията на IP адреса е част от системната администрация и не предполага директно идентифициране на посетителя. Системата за мониторинг на сайта наблюдава и други системни параметри като операционна система, вид браузер, резолюция на монитора и др., които не представляват лични данни, не могат да послужат за идентификация на потребителите и се използват за статистически цели.","Бисквитките (cookies) са малки текстови файлове, които уеб сървърът записва във вашия компютър, за да отчита трафика, който компютърът ви генерира в уебсайта. Бисквитките се обновяват всеки път, когато посетите уебсайта ни. Те не могат да послужат за идентификация - те само разпознават, че в миналото сте посетили уебсайта. Всеки сайт може да има достъп само до бисквитките, записани от него. Бисквитките не съдържат лични данни, но могат да съдържат информация, която сте въвели. Чрез бисквитките не можем да получим достъп до данни, поместени върху паметта на компютъра ви. В рамките на услугата, която предоставяме на нашите рекламодатели, е възможно те също да използват бисквитки. Възможно е да настроите браузера си да не приема бисквитки. Можете да отхвърляте и нашите бисквитки, но в този случай има риск определени функции в някои от секциите на сайта да не бъдат активни.","Функцията за помощ в менютата на повечето браузъри дава възможност да разберете повече за това как можете да предотвратите получаването на бисквитки от Вашия браузър и как да можете да бъдете предупреждаван при получаването на нови бисквитки или как да деактивирате всички новополучени бисквитки. Сходните функции като Flash Cookies, които се използват чрез Browser-Add-ons, можете да деактивирате чрез промяна на настройките на Вашия браузър или чрез интернет-страницата на производителя на съответния Browser-Add-on."]},{title:"Защита на лични данни",paragraphs:[["В случаите, в които използвате формите за Обратна връзка или Специална оферта, се съгласявате да предоставите необходимите лични данни. Изпращайки своята заявка, Вие се съгласявате с използването и съхраняването на Вашите данни от Винербергер ЕООД с цел обработка на заявката. Вашите лични данни ще бъдат третирани конфиденциално. Вашето съгласие може да бъде оттеглено по всяко време (например по телефон ",{text:"+359 2 80 66 777",href:"tel:+35928066777"}," или по имейл office.bg@wienerberger.com.) Оттеглянето на съгласието Ви не засяга законността на обработването, основано на даденото от Вас съгласие, преди неговото оттегляне. За подробна информация относно съхраняването, обработката и изтриването на данни, а също и Вашите права по използването на личните Ви данни, може да се насочите към ",{text:"Защита на личните данни",href:"https://wienerberger.bg/zashtita-lichni-danni"},"."]]},{title:"Интелектуална собственост, търговски марки и друг вид съдържание в уебсайта",paragraphs:["Ние и партньорите ни запазваме всички и всякакви права върху, но не само: запазените марки, съдържанието, в това число: текстовете, изображенията, текстовото и графичното оформление, информацията и използваните формули и всички други, както и върху кода в уебсайта, които представляват обекти на интелектуална собственост. Съдържанието в сайта може да се използва само за лична и нетърговска цел. С отварянето на този сайт, Вие се съгласявате, че всеки елемент или комбинация от елементи в и от съдържанието на този сайт са собственост на „Винербергер” ЕООД и може да се ползват само при определените от Винербергер ЕООД условия. Копирането, адаптирането или използването на текстовете и изображенията в и от уебсайта, по какъвто и да било начин, включително и публикуването на изображения чрез url-адреса им в каквито и да било интернет страници или други информационни източници, без изричното писмено съгласие на „ВИНЕРБЕРГЕР” ЕООД, ще се тълкува и третира като нарушение на правото на интелектуална собственост и ще доведе до съответните санкции и търсене на отговорност, съгласно закона.","Съдържанието на страниците на сайта в глобалната мрежа е със защитено авторско право. Каквито и да било права, които не са били изрично предоставени, са запазени. Възпроизвеждането, прехвърлянето, разпространяването или запаметяването на част или на цялото съдържание в каквато и да било форма, без предварително писмено разрешение от „ВИНЕРБЕРГЕР” ЕООД е забранено с изключение на случаите, в които то се осъществява в съответствие с настоящите условия. „ВИНЕРБЕРГЕР” ЕООД ви дава позволение да преглеждате страниците си на адрес https://www.wienerberger.bg/, респективно https://ceni.wienerberger.bg/ в глобалната мрежа, като използвате собствения си персонален компютър или друго устройство, позволяващо достъп до мрежата или да отпечатвате копия на извадки от тези страници само за ваше лично използване, но не за разпространяване, освен ако това не ви е било позволено в писмена форма от „ВИНЕРБЕРГЕР” ЕООД. В случаите, в които имате писмено разрешение за използване на https://ceni.wienerberger.bg/ съдържанието на Сайта, сте задължени да поставите хипервръзка към нас https://www.wienerberger.bg в Интернет сайтове и печатни издания, цитиране на името на уеб сайта и интернет адреса в радиостанции, изписване на името на сайта, интернет адреса и съобщаване на името му в телевизионни предавания. Някои от отделните документи в страниците на сайта могат да бъдат предмет на допълнителни условия, посочени в него. „ВИНЕРБЕРГЕР” ЕООД настоятелно ще отстоява своите права върху интелектуална собственост с цялата строгост на закона, включително и съдебно преследване.","Всеки незаконно осъществен от вас (потребителите) достъп до и чрез сайта, в това число и чрез използването на специално създадени компютърни програми („вируси”, „червеи” и др. подобни), които са предназначени да издирват или предават информация, която е различна от предоставената в сайта и за неговите цели (като, но не само: информация представляваща търговска или икономическа тайна на „Винербергер” ЕООД, информация за технология за изработване на продуктите и др.), който достъп е с цел снабдяване за себе си или за другиго с тази информация или е с цел повреждане функционирането на сайта, ще се счита за грубо нарушение на настоящите Общи условия и ще доведе до наказателна отговорност съгласно Наказателния кодекс на Република България. „Винербергер” ЕООД си запазва правото да търси обезщетение по общите граждански и търговски правила, за всяко незаконосъобразно засягане на правната сфера на „Винербергер” ЕООД, осъществено по гореописания ред."]},{title:"Собственост върху дизайна на Сайта",paragraphs:["Дизайнът настоящия сайт е собственост на „ВИНЕРБЕРГЕР” ЕООД и е защитен с авторско право. Копирането, разпространяването, поместването на част или на целия програмен сорс код или на снимки изграждащи дизайна на Сайта без предварително разрешение от „ВИНЕРБЕРГЕР” ЕООД е забранено, освен в случаите, в които то е за Ваша лична употреба за нетърговски цели."]},{title:"Отговорност",paragraphs:["Ядрото на този сайт се хоства от „ВИНЕРБЕРГЕР” ЕООД. „ВИНЕРБЕРГЕР” ЕООД не носи отговорност за временно прекратяване на функциите на сайта, независимо от причините, породили това временно спиране и независимо от неговата продължителност.","Потребителят изрично се съгласява да използва https://www.wienerberger.bg и https://ceni.wienerberger.bg/ изцяло на свой риск и отговорност и се задължава да не търси съдебна отговорност от „ВИНЕРБЕРГЕР” ЕООД, респективно – от неговите собственици и служители, за вреди, настъпили в резултат на ползването на услугите на сайта. „ВИНЕРБЕРГЕР” ЕООД не носи отговорност за щети, които могат да са в резултат на преглеждането на страниците на уебсайта. Това включва ограничаване на отговорността за преки и косвени щети, включително и загуби в резултат от случайни фактори.","„ВИНЕРБЕРГЕР” ЕООД си запазва правото по всяко време да извършва промени без предупреждение.","Информацията, публикувана на сайта и свързана с цени и ценообразуване по отношение на продуктите, които „Винербергер“ ЕООД предлага на българския пазар, е с изцяло необвързващ и примерен характер. Всички евентуално посочени на сайта цени са определени на основата на приблизителната стойност на продукта, доставен при условията на търговия на едро до определена точка на територията на Република България при средни цени за съответния вид транспорт от мястото на производство на съответния продукт (съгласно оферти и условия за транспорт, достъпни от сайта https://www0.speditor.net/cgi-bin/wienerberger/offers.pl. Тези стойности са получени въз основа на информацията, актуална единствено и само към момента на изчислението. Всякакви последващи изменения са напълно възможни и допустими и не водят до никакви претенции спрямо „Винербергер“ ЕООД. В частност, „Винербергер“ ЕООД не носи отговорност за информацията, залегнала в примерната калкулация, която е почерпена от източници, различни от групата предприятия на Винербергер.","Тези крайни стойности са примерни и с цел да онагледят един от възможните начини за изчисление на цена на продукта, доставен в различни части на страната. Тези цени нито засягат правото на всеки търговец да определя за целите на своята търговска дейност различни от тези цени и/или търговски условия, нито създават задължение за „Винербергер“ ЕООД да доставя на потребители и търговци продуктите си на посочените примерни цени. При всички случаи официалната ценова листа на „Винербергер“ ЕООД има приоритет в отношенията с търговци и потребители и посочените на този сайт цени не пораждат права или правни очаквания в тежест на „Винербергер“ ЕООД. Сайтът може да съдържа връзки към други сайтове, където „ВИНЕРБЕРГЕР” ЕООД няма контрол и не носи отговорност за съдържанието на намиращата се там информация. Връзката към други сайтове не означава, че „ВИНЕРБЕРГЕР” ЕООД одобрява предлаганите там продукти или услуги. Достъпът до такива други сайтове е изцяло за сметка и на отговорност на потребителя."]},{title:"Реклами на трети лица",paragraphs:['На страниците на сайта на „ВИНЕРБЕРГЕР” ЕООД е възможно да бъдат публикувани рекламни елементи и/или послания на трети лица. Във връзка с услугата, която „ВИНЕРБЕРГЕР” ЕООД предоставя на своите рекламодатели, е възможно трети лица да изискват браузерът на потребителя да помести и чете "бисквитки" (cookies) на потребителския компютър или да използват уеб "указатели" (beacons). Тази информация не включва Вашето име, адрес, имейл адрес, телефонен номер или друго, с което можете да бъдете лично идентифицирани. Тя включва само посещенията Ви на този и други уебсайтове и се използва с цел да се показват реклами за стоки и услуги, които може да представляват интерес за вас.']},{title:"Промяна на Условията",paragraphs:["„ВИНЕРБЕРГЕР” ЕООД може по всяко време, без предизвестие, да промени тези Условия за ползване чрез актуализиране на този документ. Ваше е задължението да посещавате периодично тази страница с цел да се запознаете с актуализираните Условия за ползване, тъй като те са обвързващи за вас."]},{title:"Закони и юрисдикция",paragraphs:["Тези Условия за ползване и Вашето използване на Сайта са подчинени на законите на Република България. Относно всички неуредени с тези Условия въпроси, приложение намират разпоредбите на българското законодателство. Всички спорове, породени от, свързани или отнасящи се до тези Условия, които страните не са успели да решат чрез преговори и по взаимно съгласие, се отнасят за решаване пред компетентните български съдилища.","С приемането на настоящите условия за ползване на сайта вие декларирате, че осъзнавате възможността за евентуални прекъсвания и друг вид затруднения при осъществяване на Интернет връзката до уебсайта, които могат да възникнат независимо от положената грижа от страна на „ВИНЕРБЕРГЕР” ЕООД,"]}]},a=()=>(0,s.jsx)(i.P,{content:n})},4837:(e,t,r)=>{"use strict";r.d(t,{s:()=>d});var s=r(8017),i=r(5990),n=r.n(i),a=r(9467),l=r.n(a);let h=/(https?:\/\/[^\s]+|[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,})/g,p=/[.,;:)]+$/,c=(e,t,r)=>e.startsWith("/")?(0,s.jsx)(n(),{href:e,className:l().link,children:t},r):e.startsWith("mailto:")||e.startsWith("tel:")?(0,s.jsx)("a",{href:e,className:l().link,children:t},r):(0,s.jsx)("a",{href:e,className:l().link,target:"_blank",rel:"noopener noreferrer",children:t},r),o=(e,t)=>{let r=[],s=0,i=t;for(let t of e.matchAll(h)){var n,a,l;let h=t[0],o=null!==(a=t.index)&&void 0!==a?a:0;o>s&&r.push(e.slice(s,o));let g=null!==(l=null===(n=h.match(p))||void 0===n?void 0:n[0])&&void 0!==l?l:"",d=g?h.slice(0,-g.length):h,w=d.startsWith("http")?d:"mailto:".concat(d);r.push(c(w,d,i)),i+=1,g&&r.push(g),s=o+h.length}return s<e.length&&r.push(e.slice(s)),r},g=(e,t)=>"string"==typeof e?o(e,100*t):c(e.href,e.text,100*t),d=e=>{let{value:t}=e;return(0,s.jsx)(s.Fragment,{children:"string"==typeof t?o(t,0):t.map((e,t)=>g(e,t))})}},6948:(e,t,r)=>{(window.__NEXT_P=window.__NEXT_P||[]).push(["/terms",function(){return r(2667)}])},7487:(e,t,r)=>{"use strict";r.d(t,{K:()=>h,fz:()=>l,wn:()=>a});var s=r(8017),i=r(7043),n=r(4837);let a=e=>{let{title:t,children:r}=e;return(0,s.jsxs)("section",{children:[t&&(0,s.jsx)(i.A,{variant:"h6",component:"h2",sx:{mt:4,mb:1.5,color:"text.primary"},children:t}),r]})},l=e=>{let{children:t}=e;return(0,s.jsx)(i.A,{color:"text.secondary",sx:{mb:1.5,lineHeight:1.7},children:t})},h=e=>{let{lines:t}=e;return(0,s.jsx)(s.Fragment,{children:t.map((e,t)=>(0,s.jsx)(i.A,{color:"text.secondary",sx:{lineHeight:1.7},children:(0,s.jsx)(n.s,{value:e})},t))})}},9467:e=>{e.exports={link:"richText_link__FiZPw"}}},e=>{var t=t=>e(e.s=t);e.O(0,[609,203,636,593,792],()=>t(6948)),_N_E=e.O()}]);